def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    panel_w = next((c for c in range(1, w)
                    if all(grid[r][c] == 0 for r in range(h))), w)

    def cropped_pattern(cells):
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        return tuple(tuple((r, c) in cells
                           for c in range(min_c, max_c + 1))
                     for r in range(min_r, max_r + 1))

    # Map each colored object on the right to its cropped shape.
    objects = {}
    seen = set()
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and panel_w <= nx < w
                            and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects[cropped_pattern(cells)] = color

    out = [row[:panel_w] for row in grid]
    separators = [r for r in range(h)
                  if all(grid[r][c] == bg for c in range(panel_w))]
    bounds = [-1] + separators + [h]

    for i in range(len(bounds) - 1):
        start, end = bounds[i] + 1, bounds[i + 1]
        holes = {(r, c) for r in range(start, end)
                 for c in range(1, panel_w - 1)
                 if grid[r][c] != bg}
        if not holes:
            continue
        color = objects.get(cropped_pattern(holes))
        if color is not None:
            for r, c in holes:
                out[r][c] = color

    return out
